import{z as n,x as o,o as A,c as s,q as B,j as e,D as a,d as r,s as i,S as t}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"失败模式与收束","description":"","frontmatter":{"title":"失败模式与收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/diff-map.md","filePath":"llm/diff-map.md","lastUpdated":1791063341000}'),d={name:"llm/diff-map.md"};function f(m,E,p,F,C,D){const l=o("Mermaid");return A(),s("div",null,[E[2]||(E[2]=B('<h1 id="失败模式与收束" tabindex="-1">失败模式与收束 <a class="header-anchor" href="#失败模式与收束" aria-label="Permalink to &quot;失败模式与收束&quot;">​</a></h1><div class="epigraph"><p>生成服务的故障长在端到端：图糊了、单贵了、门误杀了；排查法是从症状退到层、从层退到旋钮，而不是从爱好出发调参。</p><footer>—— 据本课程整理</footer></div><p><a href="/llm/diff-safety-watermark">上一课</a>把安全与水印装进收尾段，九个技术课全部落地。本课程最后一课做两件事：把十课编成跨层排查法，把课程收进几条线——本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>扩散服务的工单从来不说层，只说症状：「图变糊了」「单价涨了」「提示词不理我了」「高分辨率爆显存了」。同一个症状下面可能是完全不同的病：图糊可能是蒸馏学生用错了采样器配置，可能是量化校准被异常时间步带偏，也可能是输出门的过滤器误杀了正常图之后重试到了错误档位。没有从症状到层的协议，团队会在错误的层反复动刀——循环段明明没问题，却把步数加了一倍。收束的问题因此不是复述各课，是提炼：哪条症状归哪层，哪层握着哪个旋钮，动之前要先取什么证。</p><p><span class="marginnote">这套排查法像医院分诊：发烧（图糊）不直接开刀，先验血（段计时指标）定位炎症在哪一层。没有分诊协议的团队等于见发烧就切阑尾——循环段明明健康，步数翻倍白烧钱，病根还在量化校准里。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按层的失败清单，每层三件套：症状、验证、旋钮。</p><ul><li><strong>条件层</strong>：贴合度集体下降——先查条件嵌入缓存是否命中旧版本、预处理器是否升版（<a href="/llm/diff-control-serving">条件控制的服务</a>）。</li><li><strong>蒸馏层</strong>：纹理变平、局部怪纹——查采样器配置是否匹配学生契约、是否误开 CFG（<a href="/llm/diff-step-distill-tradeoff">步数蒸馏</a>）。</li><li><strong>量化层</strong>：固定纹理伪影、黑图——查校准集时间轴覆盖与解码器精度分配（<a href="/llm/diff-quantization">扩散模型的量化</a>）。</li><li><strong>批与调度层</strong>：尾延迟抖、OOM、凑批率掉——查桶设计、档位数与流量漂移（<a href="/llm/diff-batching-scheduling">批处理与调度</a>）。</li><li><strong>视频层</strong>：进度抖动、重复提交、阶段重跑——查作业幂等键与进度限频（<a href="/llm/diff-video-serving">视频生成的服务</a>）。</li><li><strong>成本层</strong>：单价漂——按单价表五项逐一归因，先查批效率与缓存命中率（<a href="/llm/diff-cost-engineering">成本工程</a>）。</li><li><strong>评测层</strong>：门禁失灵、指标与体感脱节——查样本量、参考统计版本与解码路径（<a href="/llm/diff-fid-pipeline">评测：FID 管线</a>）。</li><li><strong>安全层</strong>：误杀或漏杀——查双门判定分布、理由码与申诉回流（<a href="/llm/diff-safety-watermark">安全与水印</a>）。</li></ul><p>排查纪律沿用一条：一次只动一层的一个旋钮，动前动后跑评测管线，结果与谱系一起入账。</p><p><span class="marginnote">常见误区：「一次只动一个旋钮」在多人并行排查时最先被破坏——两人同时改了采样器和桶配置，门禁过了也说不清是谁的功劳。纪律的物化形式是谱系落盘：每次合并的变量清单里，改变项必须恰好只有一个。</span></p>',11)),(A(),e(t,null,{default:a(()=>[i(l,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYM%5B%22%E7%AB%AF%E5%88%B0%E7%AB%AF%E7%97%87%E7%8A%B6%22%5D%20--%3E%20R1%7B%22%E8%B4%A8%E9%87%8F%E5%8F%98%E4%BA%86%EF%BC%9F%22%7D%0A%20%20R1%20--%3E%7C%E6%98%AF%7C%20QUA%5B%22%E8%92%B8%E9%A6%8F%20%2F%20%E9%87%8F%E5%8C%96%20%2F%20%E6%9D%A1%E4%BB%B6%E5%B1%82%EF%BC%9A%E6%9F%A5%E9%85%8D%E7%BD%AE%E4%B8%8E%E6%A0%A1%E5%87%86%22%5D%0A%20%20SYM%20--%3E%20R2%7B%22%E6%88%90%E6%9C%AC%E6%88%96%E5%BB%B6%E8%BF%9F%E5%8F%98%E4%BA%86%EF%BC%9F%22%7D%0A%20%20R2%20--%3E%7C%E6%98%AF%7C%20COST%5B%22%E8%B0%83%E5%BA%A6%20%2F%20%E6%88%90%E6%9C%AC%E5%B1%82%EF%BC%9A%E6%9F%A5%E6%A1%B6%E3%80%81%E7%BC%93%E5%AD%98%E4%B8%8E%E5%8D%95%E4%BB%B7%E8%A1%A8%22%5D%0A%20%20SYM%20--%3E%20R3%7B%22%E6%8B%A6%E6%88%AA%E8%A1%8C%E4%B8%BA%E5%8F%98%E4%BA%86%EF%BC%9F%22%7D%0A%20%20R3%20--%3E%7C%E6%98%AF%7C%20SAF%5B%22%E5%AE%89%E5%85%A8%E5%B1%82%EF%BC%9A%E6%9F%A5%E5%8F%8C%E9%97%A8%E4%B8%8E%E7%90%86%E7%94%B1%E7%A0%81%22%5D%0A%20%20QUA%20--%3E%20FIX%5B%22%E5%8A%A8%E4%B8%80%E5%B1%82%E4%B8%80%E4%B8%AA%E6%97%8B%E9%92%AE%EF%BC%8C%E9%87%8D%E8%B7%91%E9%97%A8%E7%A6%81%22%5D%0A%20%20COST%20--%3E%20FIX%0A%20%20SAF%20--%3E%20FIX%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>收束回大图。本课程十课是两句话的展开。第一句：<strong>单请求的成本约化成一张公式</strong>——前向次数 × 单前向成本 ÷ 批效率，加固定段；推理管线单元（解剖、蒸馏、量化、批处理）把公式的每一项变成可测可调的对象。第二句：<strong>多请求的生成要变成可治理的对象</strong>——控制与生产单元（条件、视频、成本、评测、安全）把条件装配、作业、单价、质量门与内容门做成协议。与主干的分工：<a href="/llm/ddpm">DDPM</a>、<a href="/llm/latent-vae">潜空间与 VAE</a>、<a href="/llm/flow-matching">流匹配</a>、<a href="/llm/diffusion-distillation">扩散蒸馏与少步</a>、<a href="/llm/cfg-image">CFG 在图像生成</a>、<a href="/llm/video-gen-spatiotemporal">视频生成的时空建模</a>立第一性与默认；本课程把默认变成你自己负载上的实测决策——协议（段计时、单价表、成对门禁、双门审计、谱系落盘）跨模型与硬件复用，常数（步数、\\(\\gamma\\)、精度分配、桶配置、水印强度）每次换代重测。</p>',2)),(A(),e(t,null,{default:a(()=>[i(l,{id:"mermaid-77",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20PIPE%5B%22%E6%8E%A8%E7%90%86%E7%AE%A1%E7%BA%BF%E5%8D%95%E5%85%83%3A%20%E4%B8%80%E5%BC%A0%E6%88%90%E6%9C%AC%E5%85%AC%E5%BC%8F%22%5D%0A%20%20%20%20P1%5B%22%E5%89%8D%E5%90%91%E6%AC%A1%E6%95%B0%3A%20%E6%AD%A5%E6%95%B0%20%C3%97%20%E5%BC%95%E5%AF%BC%3Cbr%2F%3E%E8%92%B8%E9%A6%8F%E8%AF%BE%E7%AE%A1%22%5D%20--%3E%20P2%5B%22%E5%8D%95%E5%89%8D%E5%90%91%E6%88%90%E6%9C%AC%3A%20%E7%B2%BE%E5%BA%A6%E4%B8%8E%E5%AE%9E%E7%8E%B0%3Cbr%2F%3E%E9%87%8F%E5%8C%96%E8%AF%BE%E7%AE%A1%22%5D%0A%20%20%20%20P2%20--%3E%20P3%5B%22%E6%89%B9%E6%95%88%E7%8E%87%3A%20%E6%A1%B6%E4%B8%8E%E6%A1%A3%E4%BD%8D%3Cbr%2F%3E%E8%B0%83%E5%BA%A6%E8%AF%BE%E7%AE%A1%22%5D%0A%20%20%20%20P3%20--%3E%20P4%5B%22%E5%9B%BA%E5%AE%9A%E6%AE%B5%3A%20%E6%9D%A1%E4%BB%B6%E8%A3%85%E9%85%8D%E4%B8%8E%E8%A7%A3%E7%A0%81%3Cbr%2F%3E%E6%9D%A1%E4%BB%B6%E8%AF%BE%E7%AE%A1%22%5D%0A%20%20end%0A%20%20subgraph%20GOV%5B%22%E6%8E%A7%E5%88%B6%E4%B8%8E%E7%94%9F%E4%BA%A7%E5%8D%95%E5%85%83%3A%20%E4%B8%80%E7%BB%84%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20%20%20G1%5B%22%E6%AE%B5%E8%AE%A1%E6%97%B6%20%2B%20%E5%8D%95%E4%BB%B7%E8%A1%A8%22%5D%20--%3E%20G2%5B%22%E6%88%90%E5%AF%B9%E9%97%A8%E7%A6%81%20%2B%20%E5%8F%8C%E9%97%A8%E5%AE%A1%E8%AE%A1%22%5D%0A%20%20%20%20G2%20--%3E%20G3%5B%22%E8%B0%B1%E7%B3%BB%E8%90%BD%E7%9B%98%20%2B%20%E5%A4%B1%E8%B4%A5%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20end%0A%20%20PIPE%20--%3E%20MERGE%5B%22%E5%8D%8F%E8%AE%AE%E8%B7%A8%E6%8D%A2%E4%BB%A3%E5%A4%8D%E7%94%A8%3Cbr%2F%3E%E5%B8%B8%E6%95%B0%E6%AF%8F%E6%AC%A1%E6%8D%A2%E4%BB%A3%E9%87%8D%E6%B5%8B%22%5D%0A%20%20GOV%20--%3E%20MERGE%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">把公式背下来：单图成本 = 步数 × 引导倍数 × 单前向成本 ÷ 批效率 + 固定段 + 分摊。代入一例：30 步 × 2 倍引导 × 20 毫秒 ÷ 0.5 = 2.4 秒 GPU 时间，固定段与分摊常再各占零点几秒。十课的分工，就是给这五项各配一个认领人和一个旋钮。</span></p><p><span class="marginnote">一句自检：任何「扩散服务优化」若说不清动的是单价公式哪一项、门禁哪条线、谱系哪一维，它就还是技巧——技巧在模型或流量换代时静默失效，协议不会。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>清单不能替代段计时数据：先看指标在哪层变，再动旋钮。深钻层收束一门课，不收束一个领域：底座、蒸馏配方与流量档位都会换代，本课程的常数会过期，公式与协议不过期。主干之后的空白——新的采样范式、端侧扩散、交互式编辑——另课交接，不在此处展开。维护一张活的失败台账：每个新故障按三件套入册，台账比清单多一层时间，是团队真正的记忆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>排查协议：症状到层，层到旋钮；一次动一个，动前动后跑门禁。</li><li>推理管线单元给公式：前向次数 × 单前向成本 ÷ 批效率，加固定段。</li><li>控制与生产单元给协议：条件装配、异步作业、单价表、评测门禁、双门审计。</li><li>主干立第一性，深钻把你自己的负载变成决策；协议复用，常数重测。</li><li>段计时与谱系落盘是归因的前提，失败台账随时间生长。</li><li>出处：本课程各课口径汇总；Ho 等、Rombach 等、Salimans &amp; Ho、Heusel 等见各课小节。</li></ul>',6))])}const _=n(d,[["render",f]]);export{g as __pageData,_ as default};
